import { openai } from '@ai-sdk/openai';
import { generateText } from 'ai';
import { NextRequest } from 'next/server';

/**
 * 生成对话标题API路由
 */
export async function POST(req: NextRequest) {
  try {
    const { prompt } = await req.json();

    if (!prompt || typeof prompt !== 'string') {
      return new Response('Invalid prompt', { status: 400 });
    }

    // 生成标题的prompt
    const titlePrompt = `Based on the following user prompt, generate a concise title (3-6 words) that summarizes the main intent or topic. The title should be clear and descriptive.

User prompt: "${prompt}"

Generate only the title, nothing else:`;

    const result = await generateText({
      model: openai(process.env.MODEL || 'gpt-4'),
      baseURL: process.env.OPENAI_BASE_URL,
      apiKey: process.env.OPENAI_API_KEY,
      prompt: titlePrompt,
      temperature: 0.3,
      maxTokens: 20,
    });

    const title = result.text.trim().replace(/['"]/g, '');

    return Response.json({ title });

  } catch (error) {
    console.error('Title generation error:', error);
    return new Response('Internal Server Error', { status: 500 });
  }
}

