// 处理提交
const handleSubmit = async () => {
  if (state.userInput.trim()) {
    onStateTransition(id, 'SUBMIT_PROMPT');
    onUpdateState(id, { isSubmitting: true });

    try {
      // 1. 生成标题
      const titleResponse = await fetch('/api/ai/title', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: state.userInput }),
      });

      if (titleResponse.ok) {
        const { title } = await titleResponse.json();
        onUpdateState(id, { title });
      }

      // 2. 开始生成内容
      onStateTransition(id, 'AI_START_GENERATING');
      onUpdateState(id, { 
        isSubmitting: false, 
        isGenerating: true,
        aiResponse: ""
      });

      // 3. 流式响应
      const response = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          messages: [{ role: 'user', content: state.userInput }],
          gid: 'demo-1001'
        }),
      });

      if (response.ok && response.body) {
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let accumulatedResponse = '';

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = decoder.decode(value, { stream: true });
          const lines = chunk.split('\n').filter(line => line.trim() !== '');

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              const data = line.slice(6);
              if (data === '[DONE]') {
                onUpdateState(id, { isGenerating: false });
                return;
              }

              try {
                const parsed = JSON.parse(data);
                if (parsed.choices?.[0]?.delta?.content) {
                  accumulatedResponse += parsed.choices[0].delta.content;
                  onUpdateState(id, { aiResponse: accumulatedResponse });
                }
              } catch (e) {
                // 忽略解析错误
              }
            }
          }
        }
      }

    } catch (error) {
      console.error('AI request failed:', error);
      onUpdateState(id, { 
        isSubmitting: false, 
        isGenerating: false,
        aiResponse: "Sorry, something went wrong. Please try again."
      });
    }
  }
};

