   100→
   101→// 状态转换逻辑
   102→export class AIStateMachine {
   103→  private state: AIState = 'before-input';
   104→  private listeners: ((state: AIState) => void)[] = [];
   105→
   106→  getCurrentState(): AIState {
   107→    return this.state;
   108→  }
   109→
   110→  transition(event: AIEvent): void {
   111→    const newState = this.getNextState(this.state, event);
   112→    if (newState !== this.state) {
   113→      this.state = newState;
   114→      this.notifyListeners();
   115→    }
   116→  }
   117→
   118→  subscribe(listener: (state: AIState) => void): () => void {
   119→    this.listeners.push(listener);
   120→    return () => {
   121→      this.listeners = this.listeners.filter(l => l !== listener);
   122→    };
   123→  }
   124→
   125→  private notifyListeners(): void {
   126→    this.listeners.forEach(listener => listener(this.state));
   127→  }
   128→
   129→  private getNextState(currentState: AIState, event: AIEvent): AIState {
   130→    const transitions: Record<AIState, Partial<Record<AIEvent, AIState>>> = {
   131→      'before-input': {
   132→        'FOCUS_INPUT': 'input-on-focus'
   133→      },
   134→      'input-on-focus': {
   135→        'ENTER_TEXT': 'prompt-entered',
   136→        'BLUR_INPUT': 'before-input'
   137→      },
   138→      'prompt-entered': {
   139→        'SUBMIT_PROMPT': 'submitting-state',
   140→        'BLUR_INPUT': 'before-input'
   141→      },
   142→      'submitting-state': {
   143→        'AI_START_GENERATING': 'generating'
   144→      },
   145→      'generating': {
   146→        'AI_ASK_QUESTION': 'generating-with-ai-question',
   147→        'START_STRUCTURED_GENERATION': 'ai-generating-structured-content'
   148→      },
   149→      'generating-with-ai-question': {
   150→        'USER_SELECT_THREAD': 'thread-continuation'
   151→      },
   152→      'thread-continuation': {
   153→        'ENTER_THREAD_TEXT': 'thread-input-filled'
   154→      },
   155→      'thread-input-filled': {
   156→        'SUBMIT_THREAD': 'prompt-sending-process'
   157→      },
   158→      'prompt-sending-process': {
   159→        'COLLAPSE_CONVERSATION': 'conversation-collapsed'
   160→      },
   161→      'conversation-collapsed': {
   162→        'START_STRUCTURED_GENERATION': 'ai-generating-structured-content'
   163→      },
   164→      'ai-generating-structured-content': {
   165→        'COMPLETE_GENERATION': 'generation-completed'
   166→      },
   167→      'generation-completed': {}
   168→    };
   169→
   170→    return transitions[currentState][event] || currentState;
   171→  }
   172→}
   173→
   174→// 块管理器 - 管理多个独立的块
   175→export class BlockManager {
   176→  private blocks: Map<string, PromptResponseBlock> = new Map();
   177→  private listeners: ((appState: AppState) => void)[] = [];
   178→
   179→  constructor() {
   180→    // 创建初始块
   181→    this.createNewBlock();
   182→  }
   183→
   184→  // 创建新块
   185→  createNewBlock(autoFocus: boolean = false): string {
   186→    const id = this.generateBlockId();
   187→    const stateMachine = new AIStateMachine();
   188→
   189→    const block: PromptResponseBlock = {
   190→      id,
   191→      createdAt: Date.now(),
   192→      state: {
   193→        currentState: autoFocus ? 'input-on-focus' : 'before-input',
   194→        userInput: '',
   195→        threadInput: '',
   196→        aiResponse: '',
   197→        isInputFocused: autoFocus,
   198→        isSubmitting: false,
   199→        isGenerating: false,
   200→        conversationHistory: []
   201→      },
   202→      stateMachine
   203→    };
   204→
   205→    // 如果自动聚焦，转换状态机到输入状态
